public int minimumSwaps(int[] arr) {
    int n = arr.length;
    int swaps = 0;
    for (int i = 0; i < n; i++) {
        while (arr[i] != i + 1) {
            int k = -1;
            for (int j = i + 1; j < n; j++) {
                if (arr[j] == i + 1) {
                    k = j;
                    break;
                }
            }
            int tmp = arr[i];
            arr[i] = arr[k];
            arr[k] = tmp;
            swaps++;
        }
    }
    return swaps;
}

