public int minimumSwaps(int[] arr) {
    int n = arr.length;
    boolean[] visited = new boolean[n];
    int swaps = 0;
    for (int i = 0; i < n; i++) {
        if (visited[i] || arr[i] == i + 1) {
            continue;
        }
        int cycleSize = 0;
        int j = i;
        while (!visited[j]) {
            visited[j] = true;
            j = arr[j] - 1;
            cycleSize++;
        }
        swaps += cycleSize - 1;
    }
    return swaps;
}
